    L3VPN_CUST1 {
        description "Between PE1 & PE2";
        instance-type vrf;
        interface ge-0/1/0.0;
        route-distinguisher 33:33;
        vrf-target target:33:33;
        vrf-table-label;
        protocols {
            ospf {
                area 0.0.0.1 {
                    interface ge-0/1/0.0;
                }
            }
        }
    }

